def draw_lines_on_image(img, line_contours, selected_lines=None):
    """Draws all detected line segments and highlights selected ones."""
    if selected_lines is None:
        selected_lines = set()
    draw = ImageDraw.Draw(img)
    # 1. Draw all detected segments faintly
    if line_contours:
        for contour in line_contours:
            points = [tuple(p[0]) for p in contour]
            if len(points) > 1:
                draw.line(points, fill=(0, 191, 255, 100), width=2)

    # 2. Draw selected segments brightly
    if selected_lines:
        for line_idx in selected_lines:
            if line_idx < len(line_contours):
                contour = line_contours[line_idx]
                points = [tuple(p[0]) for p in contour]
                if len(points) > 1:
                    draw.line(points, fill=(50, 205, 50, 220), width=4)
    del draw

